//! Exact `Signature` header fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use keri_cesr::crypto::salt::{KeyDerivationProfile, Salt, SecurityTier};
use keri_cesr::crypto::signature::{IndexedSignature, UnindexedSignature};
use keri_cesr::crypto::signer::{SignaturePlacement, Signer};
use keri_cesr::crypto::verifier::{KeyTransferability, VerificationKey};
use serde::Deserialize;
use signify_http::signature::fields::{
    FieldText, IndexedMarker, OpaqueMarker, Signage, SignageBuilder, SignageMarkers, SignatureFieldError,
    SignatureHeader, UnindexedMarker,
};

const REFERENCE_SHA: &str = "ae92eceb8e776ad57669707bff7f84db9390b711";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    signers: Signers,
    prefix: String,
    cases: Vec<HeaderCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct Signers {
    salt: String,
    tier: String,
    temporary_profile: bool,
    paths: Vec<String>,
    signed_text: String,
    verification_keys: Vec<String>,
    indexed_signatures: Vec<String>,
    unindexed_signatures: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct HeaderCase {
    name: String,
    note: String,
    signages: Vec<SignageCase>,
    header: String,
    header_length: usize,
    reparsed: Vec<ReparsedSignage>,
}

#[derive(Debug, Deserialize)]
struct SignageCase {
    indexed: Option<bool>,
    signer: Option<String>,
    ordinal: Option<String>,
    digest: Option<String>,
    kind: Option<String>,
    markers: Vec<MarkerCase>,
}

#[derive(Debug, Deserialize)]
struct MarkerCase {
    tag: Option<String>,
    value: String,
    kind: String,
    #[serde(default)]
    verification_key: Option<String>,
}

#[derive(Debug, Deserialize)]
struct ReparsedSignage {
    indexed: bool,
    signer: Option<String>,
    ordinal: Option<String>,
    digest: Option<String>,
    kind: Option<String>,
    markers: Vec<MarkerCase>,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    a_tag_forges_header_fields: InjectionQuirk,
    a_value_forges_header_fields: InjectionQuirk,
    only_the_first_space_is_removed: SpaceQuirk,
    an_item_without_a_value_crashes: CrashQuirk,
    an_empty_header_crashes: CrashQuirk,
    a_value_containing_equals_is_truncated: CrashQuirk,
    quotes_are_stripped_from_anywhere: CrashQuirk,
    the_indexed_flag_is_true_unless_it_matches_falsy: FlagQuirk,
    a_repeated_tag_drops_a_signature: ParsedQuirk,
    a_marker_tagged_as_a_parameter_disappears: ParsedQuirk,
    an_empty_signage_is_accepted: EmptyQuirk,
    marker_and_flag_disagreement_throws: DisagreementQuirk,
}

#[derive(Debug, Deserialize)]
struct InjectionQuirk {
    header: String,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct SpaceQuirk {
    corrupted_tag: Vec<ParsedSignage>,
    unparsable: CrashQuirkValue,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct CrashQuirkValue {
    threw: bool,
    error_message: Option<String>,
}

#[derive(Debug, Deserialize)]
struct CrashQuirk {
    threw: bool,
    error_category: Option<String>,
    error_message: Option<String>,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct FlagQuirk {
    zero: bool,
    garbage: bool,
    empty: bool,
    falsy: Vec<String>,
    truthy: Vec<String>,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ParsedQuirk {
    parsed: Vec<ParsedSignage>,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct EmptyQuirk {
    emitted: String,
    parsed: Vec<ParsedSignage>,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct DisagreementQuirk {
    indexed_signature_unindexed_flag: CrashOnly,
    unindexed_signature_indexed_flag: CrashOnly,
    unindexed_signature_without_key: CrashOnly,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct CrashOnly {
    threw: bool,
    error_message: Option<String>,
}

#[derive(Debug, Deserialize)]
struct ParsedSignage {
    indexed: bool,
    signer: Option<String>,
    kind: Option<String>,
    markers: Vec<ParsedMarker>,
}

#[derive(Debug, Deserialize)]
struct ParsedMarker {
    tag: String,
    value: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/http-ending/v1.json"
    )))?)
}

/// Rebuilds the three signers the reference derived, from the same salt and paths.
fn derive_signers(signers: &Signers) -> Result<Vec<Signer>, Box<dyn Error>> {
    assert_eq!(signers.tier, "low");
    assert!(signers.temporary_profile);
    let salt = Salt::from_raw(signers.salt.as_bytes(), SecurityTier::Low)?;
    signers
        .paths
        .iter()
        .map(|path| {
            Ok(salt.derive_signer_with_profile(
                path,
                KeyTransferability::Transferable,
                KeyDerivationProfile::Temporary,
            )?)
        })
        .collect()
}

/// Rebuilds one recorded signage with the Rust builder.
fn rebuild(case: &SignageCase) -> Result<Signage, Box<dyn Error>> {
    let markers = match case.markers.first().map(|marker| marker.kind.as_str()) {
        Some("indexed") => {
            let markers = case
                .markers
                .iter()
                .map(|marker| {
                    let signature = IndexedSignature::from_qb64(&marker.value)?;
                    Ok(match &marker.tag {
                        Some(tag) => IndexedMarker::named(FieldText::new(tag.clone())?, signature)?,
                        None => IndexedMarker::new(signature),
                    })
                })
                .collect::<Result<Vec<_>, Box<dyn Error>>>()?;
            SignageMarkers::Indexed(markers)
        }
        Some("unindexed") => {
            let markers = case
                .markers
                .iter()
                .map(|marker| {
                    let signature = UnindexedSignature::from_qb64(&marker.value)?;
                    // The reference tags an unnamed marker with its own key, so the marker has to
                    // carry one; the fixture records which key that is.
                    let Some(tag) = &marker.tag else {
                        let key = marker
                            .verification_key
                            .as_deref()
                            .ok_or("an unnamed unindexed marker needs a recorded key")?;
                        let signature = signature.with_verifier(VerificationKey::from_qb64(key)?)?;
                        return Ok(UnindexedMarker::new(signature)?);
                    };
                    Ok(UnindexedMarker::named(FieldText::new(tag.clone())?, signature)?)
                })
                .collect::<Result<Vec<_>, Box<dyn Error>>>()?;
            SignageMarkers::Unindexed(markers)
        }
        Some(_) => {
            let markers = case
                .markers
                .iter()
                .map(|marker| {
                    let tag = marker.tag.clone().ok_or("an opaque marker needs a tag")?;
                    Ok(OpaqueMarker::new(
                        FieldText::new(tag)?,
                        FieldText::new(marker.value.clone())?,
                    )?)
                })
                .collect::<Result<Vec<_>, Box<dyn Error>>>()?;
            SignageMarkers::Opaque {
                indexed: case.indexed.unwrap_or(false),
                markers,
            }
        }
        None => return Err("a recorded signage has no markers".into()),
    };

    let mut builder = SignageBuilder::new(markers);
    if let Some(signer) = &case.signer {
        builder = builder.signer(FieldText::new(signer.clone())?);
    }
    if let Some(ordinal) = &case.ordinal {
        builder = builder.ordinal(FieldText::new(ordinal.clone())?);
    }
    if let Some(digest) = &case.digest {
        builder = builder.digest(FieldText::new(digest.clone())?);
    }
    if let Some(kind) = &case.kind {
        builder = builder.kind(FieldText::new(kind.clone())?);
    }
    Ok(builder.build()?)
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert!(!fixture.generated_on.is_empty());
    assert_eq!(fixture.sources, ["src/keri/end/ending.ts", "test/end/ending.test.ts"]);
    assert_eq!(fixture.prefix.len(), 44);
    Ok(())
}

/// The whole chain: the same salt derives the same keys, which sign the same text, producing the
/// exact signature material the reference's headers carry.
#[test]
fn the_recorded_signatures_are_reproduced_from_their_salt() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let signers = derive_signers(&fixture.signers)?;
    let text = fixture.signers.signed_text.as_bytes();

    for (index, signer) in signers.iter().enumerate() {
        let key = signer.verifier().qb64()?;
        assert_eq!(
            Some(&key),
            fixture.signers.verification_keys.get(index),
            "derived key {index} differs",
        );

        let indexed = signer.sign_indexed(text, SignaturePlacement::both_lists(u32::try_from(index)?))?;
        assert_eq!(
            Some(&indexed.qb64()?),
            fixture.signers.indexed_signatures.get(index),
            "indexed signature {index} differs",
        );

        let unindexed = signer.sign_unindexed(text)?;
        assert_eq!(
            Some(&unindexed.qb64()?),
            fixture.signers.unindexed_signatures.get(index),
            "unindexed signature {index} differs",
        );
    }
    Ok(())
}

#[test]
fn every_reference_header_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 7);

    for case in &fixture.cases {
        assert!(!case.note.is_empty(), "case {} has no note", case.name);
        assert_eq!(case.header.len(), case.header_length, "case {}", case.name);

        let signages = case
            .signages
            .iter()
            .map(rebuild)
            .collect::<Result<Vec<_>, Box<dyn Error>>>()?;
        let header = SignatureHeader::new(signages)?;
        assert_eq!(
            header.to_header_value()?,
            case.header,
            "case {} bytes differ",
            case.name
        );

        // The same bytes parse back into the same value, so the round trip is closed in Rust.
        let parsed = SignatureHeader::parse(&case.header)?;
        assert_eq!(parsed, header, "case {} did not survive parsing", case.name);
        assert_eq!(parsed.to_header_value()?, case.header, "case {}", case.name);

        // Reverse direction: the reference read these exact bytes and recovered these fields.
        assert_eq!(case.reparsed.len(), parsed.signages().len(), "case {}", case.name);
        for (recorded, signage) in case.reparsed.iter().zip(parsed.signages()) {
            assert_eq!(recorded.indexed, signage.is_indexed(), "case {}", case.name);
            assert_eq!(recorded.signer.as_deref(), signage.signer(), "case {}", case.name);
            assert_eq!(recorded.ordinal.as_deref(), signage.ordinal(), "case {}", case.name);
            assert_eq!(recorded.digest.as_deref(), signage.digest(), "case {}", case.name);
            // The reference defaults an absent `kind` to CESR on parse; Rust keeps the field
            // absent so the header re-renders unchanged.
            let expected_kind = signage.kind().or(Some("CESR"));
            assert_eq!(recorded.kind.as_deref(), expected_kind, "case {}", case.name);
            assert_eq!(
                recorded.markers.len(),
                signage.markers().len(),
                "case {} marker count",
                case.name
            );
        }
    }
    Ok(())
}

#[test]
fn header_injection_through_tags_and_values_is_refused() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // 1. A tag carrying the delimiters produces a header with a forged extra field.
    let tag = &quirks.a_tag_forges_header_fields;
    // The tag's own quotes close the field early, so the header carries `b="c="…` as an extra
    // item that a parser reads as real.
    assert!(tag.header.contains(r#"a";b="c="#));
    assert!(!tag.note.is_empty());
    assert_eq!(tag.rust_error_category, "InvalidFieldText");
    assert!(matches!(
        FieldText::new(r#"a";b="c"#),
        Err(SignatureFieldError::InvalidFieldText { .. })
    ));

    // 2. A value can inject a second `indexed` flag into its own signage.
    let value = &quirks.a_value_forges_header_fields;
    assert_eq!(value.header.matches("indexed=").count(), 2);
    assert_eq!(value.rust_error_category, "InvalidFieldText");
    assert!(matches!(
        FieldText::new(r#"val";indexed="?0"#),
        Err(SignatureFieldError::InvalidFieldText { .. })
    ));
    Ok(())
}

#[test]
fn reference_parser_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let siger = fixture.signers.indexed_signatures.first().ok_or("no signature")?;

    // 3. Only the first space is removed, so later tags keep one.
    let spaces = &quirks.only_the_first_space_is_removed;
    let corrupted = spaces
        .corrupted_tag
        .first()
        .and_then(|signage| signage.markers.get(1))
        .ok_or("no second marker")?;
    assert_eq!(corrupted.tag, " 1", "the tag was not corrupted upstream");
    assert!(
        corrupted.value.starts_with("AB"),
        "the corrupted marker still holds its signature"
    );
    assert!(spaces.corrupted_tag.first().is_some_and(|signage| signage.indexed));
    assert!(
        spaces
            .corrupted_tag
            .iter()
            .all(|signage| signage.kind.as_deref() == Some("CESR"))
    );
    // With a space before a later `indexed`, the header does not parse at all upstream.
    assert!(spaces.unparsable.threw);
    assert!(
        spaces
            .unparsable
            .error_message
            .as_ref()
            .is_some_and(|text| text.contains("Missing indexed field"))
    );
    assert!(!spaces.note.is_empty());
    assert!(spaces.rust_decision.contains("separators"));
    // Rust skips the whitespace instead, so both signages parse with clean tags.
    let repaired = SignatureHeader::parse(&format!(
        r#"indexed="?1"; 0="{siger}", indexed="?1"; 1="{}""#,
        fixture.signers.indexed_signatures.get(1).ok_or("no signature")?
    ))?;
    assert_eq!(repaired.signages().len(), 2);

    // 4-7. Malformed items crash upstream or silently change the value.
    for (quirk, header) in [
        (
            &quirks.an_item_without_a_value_crashes,
            r#"indexed="?1";garbage"#.to_owned(),
        ),
        (&quirks.an_empty_header_crashes, String::new()),
        (
            &quirks.a_value_containing_equals_is_truncated,
            r#"indexed="?1";0="a=b""#.to_owned(),
        ),
        (
            &quirks.quotes_are_stripped_from_anywhere,
            r#"indexed="?1";0="a"b"c""#.to_owned(),
        ),
    ] {
        assert!(quirk.threw, "{header:?} did not fail upstream");
        assert!(quirk.error_category.is_some());
        assert!(quirk.error_message.is_some());
        assert!(!quirk.note.is_empty());
        assert_eq!(quirk.rust_error_category, "MalformedItem");
        assert!(
            matches!(
                SignatureHeader::parse(&header),
                Err(SignatureFieldError::MalformedItem { .. })
            ),
            "{header:?} was accepted",
        );
    }
    // Two of those are TypeErrors, which is a crash rather than a protocol failure.
    assert_eq!(
        quirks.an_item_without_a_value_crashes.error_category.as_deref(),
        Some("TypeError")
    );
    assert_eq!(
        quirks.an_empty_header_crashes.error_category.as_deref(),
        Some("TypeError")
    );

    Ok(())
}

/// The parser defects that change which signatures a verifier sees, rather than merely which text.
#[test]
fn reference_marker_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let siger = fixture.signers.indexed_signatures.first().ok_or("no signature")?;

    // 8. Everything outside FALSY is read as true, including the numeral meant to be false.
    let flag = &quirks.the_indexed_flag_is_true_unless_it_matches_falsy;
    assert!(flag.zero, "upstream no longer reads indexed=\"0\" as true");
    assert!(flag.garbage);
    assert!(flag.empty);
    assert_eq!(flag.falsy, ["false", "0", "?0", "no", "false", "False", "off"]);
    assert_eq!(flag.truthy, ["true", "1", "?1", "yes", "true", "True", "on"]);
    assert!(!flag.note.is_empty());
    assert_eq!(flag.rust_error_category, "InvalidIndexedFlag");
    for text in ["0", "maybe", ""] {
        assert!(
            matches!(
                SignatureHeader::parse(&format!(r#"indexed="{text}";0="{siger}""#)),
                Err(SignatureFieldError::InvalidIndexedFlag { .. })
            ),
            "{text:?} was accepted as a flag",
        );
    }

    // 9. A repeated tag silently drops a signature.
    let repeated = &quirks.a_repeated_tag_drops_a_signature;
    assert_eq!(
        repeated.parsed.first().map(|signage| signage.markers.len()),
        Some(1),
        "upstream kept both markers",
    );
    assert!(!repeated.note.is_empty());
    assert_eq!(repeated.rust_error_category, "DuplicateField");
    assert!(matches!(
        SignatureHeader::parse(&format!(
            r#"indexed="?1";0="{siger}";0="{}""#,
            fixture.signers.indexed_signatures.get(1).ok_or("no signature")?
        )),
        Err(SignatureFieldError::DuplicateField { .. })
    ));

    // 10. A marker tagged as a parameter becomes that parameter.
    let shadowed = &quirks.a_marker_tagged_as_a_parameter_disappears;
    let signage = shadowed.parsed.first().ok_or("no signage")?;
    assert!(signage.markers.is_empty(), "the marker survived upstream");
    assert_eq!(signage.signer.as_deref(), Some(siger.as_str()));
    assert!(!shadowed.note.is_empty());
    assert_eq!(shadowed.rust_error_category, "ReservedTag");
    assert!(matches!(
        IndexedMarker::named(FieldText::new("signer")?, IndexedSignature::from_qb64(siger)?),
        Err(SignatureFieldError::ReservedTag { .. })
    ));

    // 11. A signage asserting nothing is accepted in both directions upstream.
    let empty = &quirks.an_empty_signage_is_accepted;
    assert_eq!(empty.emitted, r#"indexed="?0""#);
    assert_eq!(empty.parsed.first().map(|signage| signage.markers.len()), Some(0));
    assert!(!empty.note.is_empty());
    assert_eq!(empty.rust_error_category, "NoMarkers");
    assert!(matches!(
        SignatureHeader::parse(r#"indexed="?1""#),
        Err(SignatureFieldError::NoMarkers)
    ));
    assert!(matches!(
        SignageBuilder::new(SignageMarkers::Indexed(Vec::new())).build(),
        Err(SignatureFieldError::NoMarkers)
    ));

    // 12. The flag can contradict the markers upstream; here it is derived from them.
    let disagreement = &quirks.marker_and_flag_disagreement_throws;
    assert!(disagreement.indexed_signature_unindexed_flag.threw);
    assert!(disagreement.unindexed_signature_indexed_flag.threw);
    assert!(disagreement.unindexed_signature_without_key.threw);
    for crash in [
        &disagreement.indexed_signature_unindexed_flag,
        &disagreement.unindexed_signature_indexed_flag,
        &disagreement.unindexed_signature_without_key,
    ] {
        assert!(crash.error_message.as_ref().is_some_and(|text| !text.is_empty()));
    }
    assert!(!disagreement.note.is_empty());
    assert!(disagreement.rust_decision.contains("derived"));
    // The first two are unrepresentable; the third is a typed error.
    assert!(matches!(
        UnindexedMarker::new(UnindexedSignature::from_qb64(
            fixture.signers.unindexed_signatures.first().ok_or("no signature")?
        )?),
        Err(SignatureFieldError::MissingVerificationKey)
    ));
    Ok(())
}

#[test]
fn the_authing_header_is_the_shape_a_request_carries() -> Result<(), Box<dyn Error>> {
    // `core/authing.ts` signs every request and attaches exactly this: one named, unindexed
    // marker. It is called out separately because it is the only shape the client ever emits.
    let fixture = fixture()?;
    let case = fixture
        .cases
        .iter()
        .find(|case| case.name == "authing_single_named_unindexed")
        .ok_or("missing authing case")?;

    let signature = UnindexedSignature::from_qb64(fixture.signers.unindexed_signatures.first().ok_or("no signature")?)?;
    let marker = UnindexedMarker::named(FieldText::new("signify")?, signature)?;
    let signage = SignageBuilder::new(SignageMarkers::Unindexed(vec![marker])).build()?;
    let header = SignatureHeader::new(vec![signage])?;
    assert_eq!(header.to_header_value()?, case.header);

    // The verifying side recovers the marker by name, which is what `verify` does.
    let parsed = SignatureHeader::parse(&case.header)?;
    let SignageMarkers::Unindexed(markers) = parsed.signages().first().ok_or("no signage")?.markers() else {
        return Err("expected unindexed markers".into());
    };
    let found = markers
        .iter()
        .find(|marker| marker.tag().is_ok_and(|tag| tag == "signify"))
        .ok_or("the signify marker was not recovered")?;
    assert_eq!(
        Some(found.signature().qb64()?),
        fixture.signers.unindexed_signatures.first().cloned()
    );
    Ok(())
}
